#!/usr/bin/env python3

"""Report account balances from a ledger file."""

import sys


def to_cents(amount):
    whole, _, frac = amount.partition(".")
    return int(whole) * 100 + int(frac.ljust(2, "0")[:2])


def format_cents(cents):
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    return f"{sign}{cents // 100}.{cents % 100:02d}"


def read_ledger(path):
    text = open(path, "rb").read().decode("utf-8")
    return text.replace("\r\n", "\n").split("\n")


def main():
    lines = read_ledger(sys.argv[1])
    n = int(lines[0].split()[1])

    balances = {}
    for index in range(n):
        account, kind, amount = lines[1 + index].rsplit(None, 2)
        if kind not in ("debit", "credit"):
            print(f"ERROR line {index + 1}")
            return
        cents = to_cents(amount)
        if kind == "debit":
            cents = -cents
        balances[account] = balances.get(account, 0) + cents

    total = 0
    ordered = sorted(balances.items(), key=lambda e: (-e[1], e[0].encode("utf-8")))
    for account, balance in ordered:
        print(f"{account} {format_cents(balance)}")
        total += balance
    print(f"TOTAL {format_cents(total)}")


main()
